export type Listener<A extends any[], R> = (...args: A) => R;

export interface Listeners<A extends any[], R> {
    notify: (...args: A) => R[];
    subscribe: (listener: Listener<A, R>) => () => void;
    clear: () => void;
}

const createListeners = <A extends any[], R = void>(): Listeners<A, R> => {
    let listeners: Listener<A, R>[] = [];

    const notify = (...args: A) => {
        return listeners.map((listener) => {
            return listener(...args);
        });
    };

    const subscribe = (listener: Listener<A, R>) => {
        listeners.push(listener);
        return () => {
            listeners.splice(listeners.indexOf(listener), 1);
        };
    };

    const clear = () => {
        listeners = [];
    };

    return {
        notify,
        subscribe,
        clear,
    };
};

export default createListeners;
export const wait = (delay: number) => new Promise<void>((resolve) => setTimeout(resolve, delay));

/**
 * Runs each chunk from a chunks array and waits after each one has run (unless it's the last one).
 */
export const runChunksDelayed = async <T>(
    chunks: number[][] = [],
    cb: (index: number) => Promise<T>,
    delay: number
) => {
    const promises = [];

    for (let i = 0; i < chunks.length; ++i) {
        promises.push(...chunks[i].map(cb));
        if (i !== chunks.length - 1) {
            await wait(delay);
        }
    }

    return Promise.all(promises);
};

export const createPromise = <T>() => {
    let resolve!: (value: T | PromiseLike<T>) => void;
    let reject!: (reason?: any) => void;

    const promise = new Promise<T>((innerResolve, innerReject) => {
        resolve = innerResolve;
        reject = innerReject;
    });

    return { promise, resolve, reject };
};
